-- What the POS closed, line by line, and each line's name per language (#197; D127 1.2 and 1.4).
-- Generated by drizzle-kit, then edited by hand: the backfills and the row-level-security steps.
-- One transaction:
--   0. `payments`, `payment_lines` and `venues` stop forcing row-level security on their owner for
--      the length of this transaction, and `payment_lines` stops touching `updated_at` (same
--      reasons as 0015, 0018 and 0019): the owner of a hosted database has no BYPASSRLS, so under
--      forced row-level security the backfills below would silently see and change no row there;
--   1. `payment_lines.closed_minor` and `closed_quantity` (what the POS closed, set by the last
--      check; null for a line not closed, which is never shown as paid) and `name` (the line's
--      `LocalizedText`, null is "Other item"), with their checks;
--   2. the backfills: the lines of a payment already past its check are closed as picked (so a
--      captured one still reads as paid), and each name is the text the guest saw under the
--      venue's default language ("Other item" becomes null);
--   3. back to normal: the trigger and forced row-level security again.

-- 0. Owner access for the backfills; undone at step 3.
ALTER TABLE "restro"."payments" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."payment_lines" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."venues" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."payment_lines" DISABLE TRIGGER "payment_lines_touch_updated_at";--> statement-breakpoint

-- 1. The columns and their checks.
ALTER TABLE "restro"."payment_lines" ADD COLUMN "name" jsonb;--> statement-breakpoint
ALTER TABLE "restro"."payment_lines" ADD COLUMN "closed_minor" bigint;--> statement-breakpoint
ALTER TABLE "restro"."payment_lines" ADD COLUMN "closed_quantity" numeric(21, 6);--> statement-breakpoint
ALTER TABLE "restro"."payment_lines" ADD CONSTRAINT "payment_lines_closed" CHECK (("restro"."payment_lines"."closed_minor" is null) = ("restro"."payment_lines"."closed_quantity" is null) and ("restro"."payment_lines"."closed_quantity" is null or "restro"."payment_lines"."closed_quantity" > 0));--> statement-breakpoint
ALTER TABLE "restro"."payment_lines" ADD CONSTRAINT "payment_lines_name" CHECK ("restro"."payment_lines"."name" is null or (jsonb_typeof("restro"."payment_lines"."name") = 'object' and "restro"."payment_lines"."name" <> '{}'::jsonb));--> statement-breakpoint

-- 2. Backfills. Lines of payments the POS already closed were closed as picked.
UPDATE "restro"."payment_lines" AS "line" SET "closed_minor" = "line"."pos_amount_minor", "closed_quantity" = "line"."quantity" FROM "restro"."payments" AS "payment" WHERE "payment"."tenant_id" = "line"."tenant_id" AND "payment"."id" = "line"."payment_id" AND "payment"."state" IN ('checked', 'closed', 'unconfirmed', 'captured');--> statement-breakpoint
-- The name the guest saw becomes a one-language name under the venue's default language; "Other item" (D75) becomes null.
UPDATE "restro"."payment_lines" AS "line" SET "name" = CASE WHEN "line"."display_name" = 'Other item' THEN NULL ELSE jsonb_build_object("venue"."default_locale", "line"."display_name") END FROM "restro"."venues" AS "venue" WHERE "venue"."tenant_id" = "line"."tenant_id" AND "venue"."id" = "line"."venue_id";--> statement-breakpoint

-- 3. Back to normal.
ALTER TABLE "restro"."payment_lines" ENABLE TRIGGER "payment_lines_touch_updated_at";--> statement-breakpoint
ALTER TABLE "restro"."venues" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."payment_lines" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."payments" FORCE ROW LEVEL SECURITY;
